const ASSETS={"subscription-review-public.jpg": "", "subscription-review-original.jpg": "", "next-level-handoff.jpg": ""};
const SECRET='0894fd1840476e7db5a549e4aa9c0de8e5cd37d3bb7672ca974bb8162b67298e';
const PASSWORD_HASHES={"puzzledpuzzler": "7d0d4704202c5ab87ab3ac01cdc9503b9b26a0fec933808f18e64e79e9d13992", "ames95": "5360a43af9cad7488e33507cc102166df1baed23f31af59fcbf5031450832a84"};
const BASE='/staff/mail/';
const enc=new TextEncoder();
const css=`*{box-sizing:border-box}body{margin:0;background:#20252b;color:#29323a;font:16px/1.65 Arial,sans-serif}a{color:#285975}header{background:#323d47;color:#edf1f3;padding:18px 26px;display:flex;justify-content:space-between}header span{color:#bac7cf;font-size:14px}main{max-width:1000px;margin:30px auto 60px;background:#f3f4f1;min-height:440px}.grid{display:grid;grid-template-columns:175px 1fr}aside{background:#e2e7e9;padding:24px 18px;font-size:14px}aside p{margin:12px 0}.active{background:#c8d5dc;padding:8px}article{padding:26px 30px}h1{font-size:25px;line-height:1.3;margin:0 0 18px}.meta{color:#66747e;font-size:14px;border-bottom:1px solid #cbd2d6;padding-bottom:20px;margin-bottom:22px}img{display:block;width:100%;height:auto}.file{display:inline-block;background:#e1e8eb;border:1px solid #bac7ce;border-radius:3px;padding:10px 16px;margin:12px 0;overflow-wrap:anywhere}.notice{border-left:3px solid #a7a99a;padding:12px 18px;background:#e7e7dd;font-size:14px;margin:22px 0}.login{max-width:430px;padding:32px;margin:60px auto;background:#f3f4f1}label{display:block;margin:18px 0 6px}input,button{font:inherit}input{width:100%;padding:10px;border:1px solid #aab7bf}button{background:#315f79;color:white;border:0;padding:10px 20px;cursor:pointer}.login button{width:100%;margin:24px 0 10px}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #a08744;outline-offset:3px}.error{color:#a3352b}.signout{background:none;color:#285975;padding:0;text-decoration:underline;font-size:14px}.small{font-size:14px;color:#66747e}@media(max-width:650px){main{margin:16px 10px}.grid{display:block}aside{display:flex;gap:18px;flex-wrap:wrap;padding:10px 20px}aside p{margin:0}article{padding:20px 16px}.login{margin:25px 15px}header{padding:14px 18px}}`;
function page(body){return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GoPuzzler / Staff mail</title><style>'+css+'</style></head><body><header><b>GoPuzzler / mail</b><span>Internal correspondence</span></header>'+body+'</body></html>'}
function response(body,type='text/html; charset=utf-8',status=200,extra={}){return new Response(body,{status,headers:{'Content-Type':type,'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','X-Robots-Tag':'noindex, nofollow','Referrer-Policy':'same-origin',...extra}})}
function redirect(path,extra={}){return response('', 'text/plain',303,{Location:BASE+path,...extra})}
function sidebar(user=null){return '<aside><p class="active">'+(user?'Mailbox':'Archive (1)')+'</p>'+(user?'<p>'+user+'</p><p><a href="'+BASE+'login">Switch account</a></p><form method="post" action="'+BASE+'logout"><button class="signout">Sign out</button></form>':'<p><a href="'+BASE+'login">Staff sign-in</a></p>')+'<p><a href="/evil/cataract.htm">Back to level 59</a></p></aside>'}
function archive(){return page('<main><div class="grid">'+sidebar()+'<article><h1>Subscription review</h1><p class="small">Public archive / personal details removed</p><img src="'+BASE+'subscription-review-public.jpg" width="1200" height="1920" alt="Censored conversation about the subscription plan"><a class="file" href="'+BASE+'subscription-review-public.jpg">subscription-review-public.jpg</a><div class="notice">Public copy. Original correspondence is retained in the recipient’s private mailbox.</div></article></div></main>')}
function login(error=''){return page('<section class="login"><h1>Sign in to your mailbox</h1><form method="post" action="'+BASE+'login"><label for="user">Username</label><input id="user" name="username" autocomplete="username" required maxlength="80"><label for="pass">Password</label><input id="pass" name="password" type="password" autocomplete="current-password" required maxlength="120"><button>Sign in</button></form><button type="button" id="forgot" style="background:none;color:#285975;text-decoration:underline;width:auto;padding:0">Forgot password?</button>'+(error?'<p class="error" role="alert">'+error+'</p>':'')+'</section>'+reminderPopup())}
function reminderPopup(){return `<style>dialog{width:min(430px,calc(100% - 32px));padding:28px;border:1px solid #aab7bf;background:#f3f4f1;color:#29323a}dialog::backdrop{background:#101820bb}dialog h2{margin:0}dialog button{margin-top:18px}#reminder-result{white-space:pre-line}</style><dialog id="recovery" aria-labelledby="recovery-title"><h2 id="recovery-title">Password reminder</h2><p>Which user's reminder would you like to retrieve?</p><form id="recovery-form"><label for="recovery-user">Username</label><input id="recovery-user" name="username" maxlength="80" required autocomplete="off"><button id="retrieve">Show reminder</button></form><p id="reminder-result" role="status" aria-live="polite"></p><button type="button" id="close-recovery">Close</button></dialog><script>
const recovery=document.getElementById('recovery'),result=document.getElementById('reminder-result'),recoveryForm=document.getElementById('recovery-form'),retrieve=document.getElementById('retrieve');
document.getElementById('forgot').onclick=()=>{recoveryForm.reset();result.textContent='';recovery.showModal();document.getElementById('recovery-user').focus()};
document.getElementById('close-recovery').onclick=()=>recovery.close();
recoveryForm.onsubmit=async(event)=>{event.preventDefault();result.textContent='';retrieve.disabled=true;try{const response=await fetch('/staff/mail/reminder',{method:'POST',body:new FormData(recoveryForm)});const data=await response.json();result.textContent=data.message;}catch{result.textContent='Unable to retrieve the reminder. Please try again.'}finally{retrieve.disabled=false}};
</script>`}
function inbox(user){
 const body=user==='puzzledpuzzler'?'<h1>Re: subscription review</h1><p class="small">Original received message / personal copy</p><img src="'+BASE+'subscription-review-original.jpg" width="1200" height="1920" alt="Original uncensored conversation"><a class="file" href="'+BASE+'subscription-review-original.jpg">subscription-review-original.jpg</a>':'<h1>Next-level handoff</h1><div class="meta">From: Amelia &lt;ames95@gopuzzler.com&gt;<br>To: Amelia &lt;ames95@gopuzzler.com&gt;<br>09 Sep / 18:31</div><p>The destination is in the handoff. Six paragraphs. You always stop reading before the end.</p><p>The code for level 60 is brutal. Keep the mechanic out of the announcement.</p><a class="file" href="'+BASE+'next-level-handoff.jpg">next-level-handoff.jpg</a><p class="small">Saved copy / Amelia</p>';
 return page('<main><div class="grid">'+sidebar(user)+'<article>'+body+'</article></div></main>')
}
async function digest(value){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',enc.encode(value)))].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function key(){return crypto.subtle.importKey('raw',enc.encode(SECRET),{name:'HMAC',hash:'SHA-256'},false,['sign','verify'])}
async function token(user){let data=user+'.'+String(Date.now()+86400000);let sig=new Uint8Array(await crypto.subtle.sign('HMAC',await key(),enc.encode(data)));return data+'.'+[...sig].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function identity(request){try{const value=(request.headers.get('Cookie')||'').split(';').map(s=>s.trim()).find(s=>s.startsWith('gp59accounts='))?.slice(13);if(!value)return null;const [user,expiry,sig]=value.split('.');if(!['puzzledpuzzler','ames95'].includes(user)||!/^\d{13}$/.test(expiry)||! /^[a-f0-9]{64}$/.test(sig)||Number(expiry)<Date.now())return null;const valid=await crypto.subtle.verify('HMAC',await key(),Uint8Array.from(sig.match(/../g),h=>parseInt(h,16)),enc.encode(user+'.'+expiry));return valid?user:null}catch{return null}}
function cookie(value,url,age=86400){return 'gp59accounts='+value+'; Path=/staff/mail; HttpOnly; SameSite=Strict; Max-Age='+age+(url.protocol==='https:'?'; Secure':'')}
export async function onRequest({request}){
 const url=new URL(request.url);let path=url.pathname.replace(/^\/staff\/mail\/?/,'').replace(/\/$/,'');
 if(request.method==='POST'){
  if(request.headers.get('Origin')&&request.headers.get('Origin')!==url.origin)return response('Forbidden','text/plain',403);
  if(path==='logout')return redirect('login',{'Set-Cookie':cookie('',url,0)});
  if(!['login','reminder'].includes(path))return response('Method not allowed','text/plain',405);
  if(Number(request.headers.get('Content-Length')||0)>4096)return response('Request too large','text/plain',413);
  let form;try{form=await request.formData()}catch{return response(login('Unable to read sign-in details.'),'text/html',400)}
  let user=String(form.get('username')||'').trim().toLowerCase(),pass=String(form.get('password')||'').trim().toLowerCase();
  if(path==='reminder'){
   const known=['puzzledpuzzler','ames95'].includes(user);
   const message=!user?'Enter a username.':user==='puzzledpuzzler'?'No password hint provided':user==='ames95'?'The name you gave my cancellation button.':'No password reminder found for that username.';
   return response(JSON.stringify({message}),'application/json; charset=utf-8',!user?400:known?200:404);
  }
  const normalized=user==='ames95'?pass.replace(/\s+/g,''):pass;
  if(Object.hasOwn(PASSWORD_HASHES,user)&&await digest(normalized)===PASSWORD_HASHES[user])return redirect('inbox',{'Set-Cookie':cookie(await token(user),url)});
  return response(login('Username or password not recognized.'),'text/html; charset=utf-8',401);
 }
 if(!['GET','HEAD'].includes(request.method))return response('Method not allowed','text/plain',405);
 const user=await identity(request);
 if(path==='inbox'&&!user)return redirect('login');
 const required={'subscription-review-original.jpg':'puzzledpuzzler','next-level-handoff.jpg':'ames95'};
 if(Object.hasOwn(required,path)){
  if(!user)return redirect('login');
  if(user!==required[path])return response(page('<main><article><h1>Attachment unavailable</h1><p>This attachment is not in this mailbox.</p><a href="'+BASE+'login">Switch account</a></article></main>'),'text/html; charset=utf-8',403);
 }
 if(Object.hasOwn(ASSETS,path)){let bytes=Uint8Array.from(atob(ASSETS[path]),c=>c.charCodeAt(0));return response(request.method==='HEAD'?null:bytes,'image/jpeg')}
 if(path===''||path==='index.htm')return response(archive());
 if(path==='login')return response(login());
 if(path==='reminder')return redirect('login');
 if(path==='inbox')return response(inbox(user));
 return response(page('<main><article><h1>Message not found</h1><a href="'+BASE+'">Return to archive</a></article></main>'),'text/html; charset=utf-8',404);
}
